import unittest
from hourglass.models import Span
from hourglass.gaps import gap_labels

OPENING = Span(540, 1020)

class GapLabelTests(unittest.TestCase):
    def test_nobody_working_is_one_gap(self):
        self.assertEqual(
            gap_labels([], OPENING),
            ["gap 09:00-17:00 (480 min)"],
        )

    def test_lunch_gap(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            gap_labels(worked, OPENING),
            ["gap 12:00-13:00 (60 min)"],
        )

    def test_gaps_at_both_ends(self):
        worked = [Span(600, 660)]
        self.assertEqual(
            gap_labels(worked, OPENING),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-17:00 (360 min)",
            ],
        )

    def test_fully_covered_has_no_gaps(self):
        self.assertEqual(gap_labels([OPENING], OPENING), [])

    def test_overlapping_spans_count_once(self):
        worked = [Span(540, 620), Span(600, 700)]
        worked += [Span(700, 800)]
        self.assertEqual(
            gap_labels(worked, OPENING),
            ["gap 13:20-17:00 (220 min)"],
        )

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            gap_labels([Span(480, 600)], OPENING)

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            gap_labels([Span(900, 1080)], OPENING)
